// row keeps the prologue's executed code contiguous (cold instruction fetch dominates short runs).
__device__ __noinline__ float2 rope_cs(float a) {
  float sn, cs;
  sincosf(a, &sn, &cs);
  return make_float2(cs, sn);
}
