  constexpr bool Z = F & F_Z, SLOT = F & F_SLOT, ZOUT = F & F_ZOUT, RSQ = F & F_RSQ, NREG = F & F_NREG;
  constexpr bool VEC=3>0&&NT==1&&!NREG,VNR=3==3&&NT==1&&!NREG;
  constexpr bool PDL = F & F_PDL, LAST = F & F_LAST, TRACE = F & F_TRACE;
  if constexpr(PDL) asm volatile("griddepcontrol.launch_dependents;" ::: "memory");
  static_assert(((F & F_NT2) != 0) == (NT == 2) && !(NT == 2 && SLOT), "F_NT2 selects NT=2 (M>1 dispatch)");
  constexpr int NB = 8 * NT;
