    for (int i = 0; i < N; i++)
      raw[i] = *(const uint32_t*)((const __nv_bfloat16*)p.qkv + (int64_t)token[i] * p.stride + col[i]);
#pragma unroll
    for (int i = 0; i < N; i++) {
      __nv_bfloat162 h;
