  }
  const float* base = (const float*)p.qkv;
#pragma unroll
  for (int i = 0; i < N; i++) x[i] = make_float2(0.f, 0.f);
#pragma unroll 2
  for (int s = 0; s < p.proj_splits; s++) {
    float2 v[N];
#pragma unroll
    for (int i = 0; i < N; i++)
      v[i] = *(const float2*)(base + (int64_t)s * p.split_stride + (int64_t)token[i] * p.stride + col[i]);
