  } else {
    if (tid == 0) {
      if (atomicAdd(cnt + C_BAR, 1) == G - 1) {
        for (int i = 0; i < NLOC; ++i) cnt[C_DONE + i] = 0;   // every CTA is past its waits
        cnt[C_ZERO] = 0;
        cnt[C_BAR] = 0;
